impl<'a> FifoIds<'a> {
    /// Applies SPEC section 6 rules on `GroupId`, `DeduplicationId` and
    /// `DelaySeconds` for this queue type; `None` for a standard queue.
    fn resolve(
        attributes: &Attributes,
        group_id: Option<&'a str>,
        deduplication_id: Option<&'a str>,
        has_delay: bool,
        body: &'a str,
